1	document.addEventListener('DOMContentLoaded',function(){
2	  if(typeof Chart==='undefined')return;
3	  document.querySelectorAll('.arbe-chart-data').forEach(function(node){
4	    try{
5	      const p=JSON.parse(node.textContent);
6	      const id=node.getAttribute('data-chart-id');
7	      const canvas=document.getElementById(id);
8	      if(!canvas)return;
9	      const datasets=[
10	        {label:p.a_label||'Reference',data:p.a||[],tension:.25,pointRadius:0,borderWidth:2},
11	        {label:p.b_label||'Formula',data:p.b||[],tension:.25,pointRadius:0,borderWidth:2,fill:'-1',backgroundColor:'rgba(15,23,42,.08)'}
12	      ];
13	      if(p.difference){
14	        datasets.push({label:'SCISSOR Difference',data:p.difference||[],tension:.25,pointRadius:0,borderWidth:1});
15	      }
16	      new Chart(canvas,{
17	        type:'line',
18	        data:{labels:p.labels||[],datasets:datasets},
19	        options:{
20	          responsive:true,
21	          plugins:{legend:{display:true}},
22	          scales:{
23	            x:{title:{display:true,text:'Wavelength λ / nm'}},
24	            y:{title:{display:true,text:'Remission R(λ) / Difference'},min:p.difference?-1:0,max:p.difference?1:1}
25	          }
26	        }
27	      });
28	    }catch(e){console.error('ARBE chart error',e)}
29	  })
30	});
