277	function arbe_fp_curve_metrics($curve) {
278	    $sum_r=0.0; $sum_wr=0.0;
279	    foreach ($curve as $wl=>$r) { $sum_r += $r; $sum_wr += $wl*$r; }
280	    $mu = $sum_r > 0 ? $sum_wr/$sum_r : 0.0;
281	
282	    $mu2=0.0; $mu3=0.0;
283	    foreach ($curve as $wl=>$r) {
284	        $d = $wl - $mu;
285	        $mu2 += $d*$d*$r;
286	        $mu3 += $d*$d*$d*$r;
287	    }
288	    $mu2 = $sum_r > 0 ? $mu2/$sum_r : 0.0;
289	    $mu3 = $sum_r > 0 ? $mu3/$sum_r : 0.0;
290	
291	    $wls = array_keys($curve); sort($wls);
292	    $energy_sum=0.0; $energy_w_sum=0.0;
293	    for ($i=1; $i<count($wls); $i++) {
294	        $wl0=$wls[$i-1]; $wl1=$wls[$i]; $step=max(1,$wl1-$wl0);
295	        $grad = abs(($curve[$wl1]-$curve[$wl0])/$step);
296	        $mid = ($wl0+$wl1)/2.0;
297	        $energy_sum += $grad;
298	        $energy_w_sum += $mid*$grad;
299	    }
300	    $lambda_ee = $energy_sum > 0 ? $energy_w_sum/$energy_sum : $mu;
301	
302	    return [
303	        'lambda_v2'=>$mu,
304	        'lambda_ee'=>$lambda_ee,
305	        'delta_lambda'=>$mu-$lambda_ee,
306	        'mu2'=>$mu2,
307	        'sigma_star'=>sqrt(max(0.0,$mu2)),
308	        'mu3'=>$mu3,
309	    ];
310	}
