312	function arbe_fp_extract_4psf($curve) {
313	    ksort($curve);
314	    $wls = array_keys($curve);
315	    $vals = array_values($curve);
316	    $min = min($vals); $max = max($vals); $span = max(0.000001, $max-$min);
317	    $r10 = $min + 0.10*$span;
318	    $r90 = $min + 0.90*$span;
319	    $rising = end($vals) >= $vals[0];
320	
321	    $p1 = ['nm'=>$wls[0], 'r'=>$vals[0]];
322	    $p3 = ['nm'=>end($wls), 'r'=>end($vals)];
323	    $p4_idx = array_search($max, $vals, true);
324	    $p4 = ['nm'=>$wls[$p4_idx], 'r'=>$vals[$p4_idx]];
325	
326	    for ($i=0; $i<count($wls); $i++) {
327	        if (($rising && $vals[$i] >= $r10) || (!$rising && $vals[$i] <= ($max - 0.10*$span))) {
328	            $p1 = ['nm'=>$wls[$i], 'r'=>$vals[$i]]; break;
329	        }
330	    }
331	    for ($i=0; $i<count($wls); $i++) {
332	        if (($rising && $vals[$i] >= $r90) || (!$rising && $vals[$i] <= ($max - 0.90*$span))) {
333	            $p3 = ['nm'=>$wls[$i], 'r'=>$vals[$i]]; break;
334	        }
335	    }
336	
337	    $best_slope=-1.0; $p2=$p1;
338	    for ($i=1; $i<count($wls); $i++) {
339	        $step=max(1,$wls[$i]-$wls[$i-1]);
340	        $slope=abs(($vals[$i]-$vals[$i-1])/$step);
341	        if ($slope > $best_slope) {
342	            $best_slope=$slope;
343	            $p2=['nm'=>intval(($wls[$i]+$wls[$i-1])/2), 'r'=>($vals[$i]+$vals[$i-1])/2.0];
344	        }
345	    }
346	
347	    return [
348	        ['nm'=>intval($p1['nm']), 'r'=>round($p1['r'],4)],
349	        ['nm'=>intval($p2['nm']), 'r'=>round($p2['r'],4)],
350	        ['nm'=>intval($p3['nm']), 'r'=>round($p3['r'],4)],
351	        ['nm'=>intval($p4['nm']), 'r'=>round($p4['r'],4)],
352	    ];
353	}
