415	function arbe_fp_resample_curve($curve, $wavelengths) {
416	    ksort($curve);
417	    $src_wls = array_keys($curve);
418	    $src_vals = array_values($curve);
419	    $out = [];
420	
421	    foreach ($wavelengths as $wl) {
422	        if (isset($curve[$wl])) {
423	            $out[$wl] = $curve[$wl];
424	            continue;
425	        }
426	        if ($wl <= $src_wls[0]) {
427	            $out[$wl] = $src_vals[0];
428	        } elseif ($wl >= $src_wls[count($src_wls)-1]) {
429	            $out[$wl] = $src_vals[count($src_vals)-1];
430	        } else {
431	            for ($i=1; $i<count($src_wls); $i++) {
432	                if ($wl <= $src_wls[$i]) {
433	                    $x0=$src_wls[$i-1]; $x1=$src_wls[$i];
434	                    $y0=$src_vals[$i-1]; $y1=$src_vals[$i];
435	                    $t=($wl-$x0)/max(1,($x1-$x0));
436	                    $out[$wl] = $y0 + $t*($y1-$y0);
437	                    break;
438	                }
439	            }
440	        }
441	    }
442	    return $out;
443	}
