4	/**
5	 * Convert remission R to Kubelka-Munk K/S.
6	 * K/S = (1 - R)^2 / (2R)
7	 */
8	function arbe_fp_r_to_ks($r) {
9	    $r = max(0.0001, min(0.9999, floatval($r)));
10	    return (($r - 1.0) * ($r - 1.0)) / (2.0 * $r);
11	}
12	
13	/**
14	 * Convert Kubelka-Munk K/S back to remission R.
15	 * Solves: x = (1-R)^2/(2R)
16	 * R = 1 + x - sqrt(x^2 + 2x)
17	 */
18	function arbe_fp_ks_to_r($ks) {
19	    $x = max(0.0, floatval($ks));
20	    $r = 1.0 + $x - sqrt(($x*$x) + (2.0*$x));
21	    return max(0.0, min(1.0, $r));
22	}
