140	/**
141	 * Adaptive local refinement.
142	 * Starts from the best grid solutions and perturbs component shares in smaller steps.
143	 * This is still remission-linear v1.1 logic, but removes the coarse 10% raster effect.
144	 */
145	function arbe_fp_adaptive_refine_results($results, $ref_curve, $seed_limit=24, $kernel='km') {
146	    if (!$results) return [];
147	    $out = $results;
148	    $seeds = array_slice($results, 0, max(1, intval($seed_limit)));
149	
150	    foreach ($seeds as $seed) {
151	        if (count($seed['formula']) < 2) continue;
152	
153	        $pigments = [];
154	        $curves = [];
155	        foreach ($seed['formula'] as $f) {
156	            $p = arbe_fp_get_pigment($f['code']);
157	            if (!$p) { $pigments = []; break; }
158	            $curve = arbe_fp_get_curve($p->id);
159	            if (!$curve) { $pigments = []; break; }
160	            $pigments[] = $p;
161	            $curves[] = $curve;
162	        }
163	        if (!$pigments) continue;
164	
165	        $weights = array_map(fn($f) => floatval($f['share']), $seed['formula']);
166	        $best = $seed;
167	        $steps = [0.05, 0.02, 0.01];
168	
169	        foreach ($steps as $delta) {
170	            $improved = true;
171	            $guard = 0;
172	
173	            while ($improved && $guard < 80) {
174	                $guard++;
175	                $improved = false;
176	                $n = count($weights);
177	
178	                for ($i=0; $i<$n; $i++) {
179	                    for ($j=0; $j<$n; $j++) {
180	                        if ($i === $j) continue;
181	                        if ($weights[$j] - $delta < 0.01) continue;
182	
183	                        $trial = $weights;
184	                        $trial[$i] += $delta;
185	                        $trial[$j] -= $delta;
186	                        $trial = arbe_fp_normalize_weights($trial);
187	
188	                        $mix = arbe_fp_mix_curves($curves, $trial, $kernel);
189	                        $cmp = arbe_fp_scissor_compare_curves($ref_curve, $mix);
190	
191	                        if ($cmp['scissor_index'] < $best['scissor']) {
192	                            $best = arbe_fp_formula_result($pigments, $trial, $mix, $cmp, count($trial) . '-component adaptive', $kernel);
193	                            $weights = $trial;
194	                            $improved = true;
195	                        }
196	                    }
197	                }
198	            }
199	        }
200	
201	        $out[] = $best;
202	    }
203	
204	    return $out;
205	}
206	
207	function arbe_fp_normalize_weights($weights) {
208	    $sum = array_sum($weights);
209	    if ($sum <= 0) return $weights;
210	    return array_map(fn($w) => max(0.0, min(1.0, $w / $sum)), $weights);
211	}
