4	function arbe_fp_scissor_compare_curves($a, $b) {
5	    $common = array_values(array_intersect(array_keys($a), array_keys($b)));
6	    sort($common);
7	
8	    $area_abs=0.0; $area_signed=0.0; $sum_sq=0.0; $max_abs=0.0; $max_abs_nm=$common[0] ?? 0; $edge_area=0.0;
9	
10	    for ($i=0; $i<count($common); $i++) {
11	        $wl=$common[$i];
12	        $d=$a[$wl]-$b[$wl];
13	        $sum_sq += $d*$d;
14	
15	        if (abs($d)>$max_abs) {
16	            $max_abs=abs($d);
17	            $max_abs_nm=$wl;
18	        }
19	
20	        if ($i>0) {
21	            $wl0=$common[$i-1]; $wl1=$common[$i]; $step=max(1,$wl1-$wl0);
22	            $d0=$a[$wl0]-$b[$wl0]; $d1=$a[$wl1]-$b[$wl1];
23	            $area_abs += $step*(abs($d0)+abs($d1))/2.0;
24	            $area_signed += $step*($d0+$d1)/2.0;
25	
26	            $ga=($a[$wl1]-$a[$wl0])/$step;
27	            $gb=($b[$wl1]-$b[$wl0])/$step;
28	            $edge_area += abs($ga-$gb)*$step;
29	        }
30	    }
31	
32	    $rmse = count($common) ? sqrt($sum_sq/count($common)) : 0.0;
33	    $scissor_index = $area_abs + 250.0*$edge_area;
34	    $similarity = max(0.0, min(100.0, 100.0 * exp(-0.018 * $scissor_index)));
35	
36	    return [
37	        'area_abs'=>$area_abs,
38	        'area_signed'=>$area_signed,
39	        'rmse'=>$rmse,
40	        'max_abs'=>$max_abs,
41	        'max_abs_nm'=>$max_abs_nm,
42	        'edge_area'=>$edge_area,
43	        'scissor_index'=>$scissor_index,
44	        'similarity'=>$similarity,
45	    ];
46	}
