48	function arbe_fp_reference_curve_from_color($color, $wavelengths) {
49	    $points = [
50	        intval($color->psf_p1_nm)=>floatval($color->psf_p1_r),
51	        intval($color->psf_p2_nm)=>floatval($color->psf_p2_r),
52	        intval($color->psf_p3_nm)=>floatval($color->psf_p3_r),
53	        intval($color->psf_p4_nm)=>floatval($color->psf_p4_r),
54	    ];
55	    ksort($points);
56	    $pwl = array_keys($points);
57	    $pr = array_values($points);
58	    $out = [];
59	
60	    foreach ($wavelengths as $wl) {
61	        if ($wl <= $pwl[0]) {
62	            $out[$wl] = $pr[0];
63	        } elseif ($wl >= $pwl[count($pwl)-1]) {
64	            $out[$wl] = $pr[count($pr)-1];
65	        } else {
66	            for ($i=1; $i<count($pwl); $i++) {
67	                if ($wl <= $pwl[$i]) {
68	                    $x0=$pwl[$i-1]; $x1=$pwl[$i]; $y0=$pr[$i-1]; $y1=$pr[$i];
69	                    $t=($wl-$x0)/max(1,($x1-$x0));
70	                    $out[$wl] = $y0 + $t*($y1-$y0);
71	                    break;
72	                }
73	            }
74	        }
75	    }
76	    return $out;
77	}
